import importlib.util
for p in ['z3','pysat','ortools']:
 print(p, importlib.util.find_spec(p))

import z3,itertools,time,pickle,os
T=6;r=2;m=T-r;n=T*m
cores=[sum(1<<(i*m+j) for j in range(m)) for i in range(T)]
cands=[];groups=[]
for i,core in enumerate(cores):
 for R in itertools.combinations([v for v in range(n) if not (core>>v&1)],r):
  cands.append(core|sum(1<<v for v in R));groups.append(i)
print(len(cands),flush=True)
x=[z3.Bool('x'+str(i)) for i in range(len(cands))]
s=z3.Solver();s.set(timeout=300000)
# one per group
for g in range(T):s.add(z3.Or([x[i] for i in range(len(x)) if groups[i]==g]))
for i,A in enumerate(cands):
 for j in range(i):
  if not A&cands[j]:s.add(z3.Or(z3.Not(x[i]),z3.Not(x[j])))
print('conflicts done',flush=True)
# constraint generation
for it in range(10000):
 ans=s.check();print(it,ans,flush=True)
 if ans!=z3.sat:break
 model=s.model();fam=[cands[i] for i in range(len(x)) if z3.is_true(model.eval(x[i]))]
 y=[z3.Bool('y'+str(i)) for i in range(n)]
 cov=z3.Solver();cov.add(z3.PbLe([(v,1) for v in y],T-1))
 for A in fam:cov.add(z3.Or([y[v] for v in range(n) if A>>v&1]))
 if cov.check()==z3.unsat:
  print('FOUND',fam);pickle.dump((T,r,m,fam),open('found.pkl','wb'));break
 cm=cov.model();C=sum(1<<v for v in range(n) if z3.is_true(cm.eval(y[v])))
 s.add(z3.Or([x[i] for i in range(len(x)) if not cands[i]&C]))
